// Model Selection Logic
// Default: FREE Gemini model
// Upgrade: Premium Claude for high-value qualified leads (ROI-positive)

const inputData = $input.first().json;

// Default to free model
let selectedModel = 'google/gemini-2.0-flash-exp:free';
let modelTier = 'free';

// Extract lead data for qualification check
const leadData = inputData.leadData || {};
const estimatedCost = leadData.estimatedCost || leadData.lastCalculatedCost || 0;
const messageCount = inputData.conversationHistory?.length || 0;
const teamSize = leadData.teamSize || 0;

// Qualification criteria for premium model upgrade
const isHighValue = estimatedCost > 5000 || teamSize > 15;
const isEngaged = messageCount > 6;
const hasEmail = !!inputData.userEmail;

// Upgrade to premium model for high-value qualified leads
// Worth ~$0.15 per request to close a potential $10K+ client
if (isHighValue && isEngaged) {
  selectedModel = 'anthropic/claude-sonnet-4';
  modelTier = 'premium';
}

// Build messages array for OpenRouter
const messages = [
  {
    role: 'system',
    content: inputData.systemPrompt
  }
];

// Add conversation history
if (inputData.conversationHistory && inputData.conversationHistory.length > 0) {
  for (const msg of inputData.conversationHistory) {
    messages.push({
      role: msg.role,
      content: msg.content
    });
  }
}

// Add current user message
messages.push({
  role: 'user',
  content: inputData.userMessage
});

return [{
  json: {
    selectedModel,
    modelTier,
    isHighValue,
    isEngaged,
    messages,
    userMessage: inputData.userMessage,
    conversationHistory: inputData.conversationHistory,
    userName: inputData.userName,
    userEmail: inputData.userEmail,
    leadData: inputData.leadData,
    timestamp: inputData.timestamp
  }
}];

// Process OpenRouter API Response
// Handles both valid JSON responses and fallback for invalid responses

const apiResponse = $input.first().json;
const prevData = $('Code - Select Model').first().json;

// Extract the AI's response content
const content = apiResponse.choices?.[0]?.message?.content;

if (!content) {
  // No response from API - return fallback
  return [{
    json: {
      reply: "I'm here to help! Could you tell me more about your operational challenges?",
      quickReplies: ["Tool integration issues", "Manual data entry", "Team coordination", "Process efficiency"],
      showCostCard: false,
      costAmount: 0,
      showCalendar: false,
      userName: prevData.userName,
      userEmail: prevData.userEmail,
      leadData: prevData.leadData,
      isQualified: false,
      modelUsed: prevData.selectedModel,
      modelTier: prevData.modelTier,
      timestamp: prevData.timestamp,
      error: 'No response from API'
    }
  }];
}

// Parse JSON response from AI
let parsedResponse;
try {
  parsedResponse = JSON.parse(content);
} catch (e) {
  // Fallback if AI didn't return valid JSON
  console.error('Failed to parse AI response as JSON:', e.message);
  parsedResponse = {
    reply: content.substring(0, 500), // Use raw content truncated
    quickReplies: [],
    showCostCard: false,
    costAmount: 0,
    showCalendar: false
  };
}

// Validate and normalize required fields
if (!parsedResponse.reply || typeof parsedResponse.reply !== 'string') {
  parsedResponse.reply = "I'm here to help! What operational challenges are you facing?";
}

// Ensure arrays/booleans have correct types
parsedResponse.quickReplies = Array.isArray(parsedResponse.quickReplies) 
  ? parsedResponse.quickReplies.slice(0, 4) // Max 4 quick replies
  : [];
parsedResponse.showCostCard = Boolean(parsedResponse.showCostCard);
parsedResponse.showCalendar = Boolean(parsedResponse.showCalendar);
parsedResponse.costAmount = Number(parsedResponse.costAmount) || 0;

// Update lead data with calculated cost
const updatedLeadData = {
  ...prevData.leadData,
  lastCalculatedCost: parsedResponse.costAmount || prevData.leadData?.lastCalculatedCost || 0
};

// Determine qualification status
// Qualified if: calendar shown OR cost > $3000 OR high engagement with cost shown
const messageCount = prevData.conversationHistory?.length || 0;
const isQualified = parsedResponse.showCalendar || 
                   parsedResponse.costAmount > 3000 ||
                   (messageCount > 4 && parsedResponse.showCostCard);

// Track API usage metadata
const usage = apiResponse.usage || {};

return [{
  json: {
    // Response data for chat
    reply: parsedResponse.reply,
    quickReplies: parsedResponse.quickReplies,
    showCostCard: parsedResponse.showCostCard,
    costAmount: parsedResponse.costAmount,
    showCalendar: parsedResponse.showCalendar,

    // Lead metadata
    userName: prevData.userName,
    userEmail: prevData.userEmail,
    leadData: updatedLeadData,
    isQualified,

    // Tracking data
    modelUsed: prevData.selectedModel,
    modelTier: prevData.modelTier,
    timestamp: prevData.timestamp,
    messageCount: messageCount + 1,
    tokensUsed: usage.total_tokens || 0
  }
}];
